// pubspec.yaml: shared_preferences: ^2.3.2
import 'package:shared_preferences/shared_preferences.dart';

// ────── Legacy sync API (still works) ──────
final prefs = await SharedPreferences.getInstance();
await prefs.setBool('dark_mode', true);
final dark = prefs.getBool('dark_mode') ?? false;

// ────── Modern async API (recommended for new code) ──────
final async = SharedPreferencesAsync();
await async.setBool('dark_mode', true);
final darkA = await async.getBool('dark_mode');

// ────── Cached async — sync reads for a known key set ──────
final cache = await SharedPreferencesWithCache.create(
  cacheOptions: const SharedPreferencesWithCacheOptions(
    allowList: {'dark_mode', 'locale', 'onboarding_done'},
  ),
);
cache.setBool('dark_mode', true);        // async write, sync return
final cachedDark = cache.getBool('dark_mode') ?? false;   // SYNC read from cache

// ────── Reading & writing all primitive types ──────
await async.setInt('counter', 42);
await async.setDouble('threshold', 0.75);
await async.setString('locale', 'en_US');
await async.setStringList('recent_searches', ['flutter', 'dio', 'hive']);

// ────── Delete + clear ──────
await async.remove('counter');
await async.clear(allowList: {'onboarding_done'});  // clear WITHOUT wiping onboarding

// ────── Repository wrapper (recommended pattern) ──────
class SettingsStore {
  SettingsStore(this._prefs);
  final SharedPreferencesWithCache _prefs;

  bool get darkMode => _prefs.getBool('dark_mode') ?? false;
  Future<void> setDarkMode(bool v) => _prefs.setBool('dark_mode', v);

  String get locale => _prefs.getString('locale') ?? 'en';
  Future<void> setLocale(String v) => _prefs.setString('locale', v);
}
